from sentence_transformers import SentenceTransformer
import numpy as np
import json

class CustomEmbeddingGenerator:
    def __init__(self, model_name: str = 'all-MiniLM-L6-v2'):
        self.model = SentenceTransformer(model_name)
        self.items = []
        self.embeddings = None

    def load_items(self, data_list):
        """
        Generate embeddings from your data list.
        Each item should have 'name' and 'meta' fields
        """
        # Prepare items by combining name and meta
        processed_items = []
        for item in data_list:
            # Combine name and meta for richer embedding
            combined_text = f"{item['name']} {item['meta']}"
            processed_items.append(combined_text.lower().strip())

        # Remove duplicates
        self.items = list(set(processed_items))
        
        # Generate embeddings
        self.embeddings = self.model.encode(self.items, show_progress_bar=True)
        print(f"Generated embeddings for {len(self.items)} unique items")
        
        # Save embeddings
        embeddings_dict = {
            'items': self.items,
            'vectors': self.embeddings.tolist()  # Convert numpy array to list
        }

        # Save to file
        with open('embeddings.json', 'w') as f:
            json.dump(embeddings_dict, f)
            print("Saved embeddings to embeddings.json")

